import{_ as r,C as d,o as a,c as s,E as o,a3 as n}from"./chunks/framework.hkNkIkN3.js";const l="/versions/v0.19.10/screens/devices/envelope.png",b=JSON.parse('{"title":"Envelope","description":"","frontmatter":{"title":"Envelope","pageClass":"device-doc"},"headers":[],"relativePath":"devices/envelope.md","filePath":"devices/envelope.md"}'),i={name:"devices/envelope.md"};function h(g,t,c,p,y,u){const e=d("DeviceHeading");return a(),s("div",null,[o(e,{slug:"envelope",title:"Envelope"}),t[0]||(t[0]=n('<p>ADSR envelope on MIDI</p><p><img src="'+l+'" alt="Envelope parameters" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Place <strong>Envelope</strong> when a <strong>CC, pitch bend, or other MIDI destination</strong> should follow an ADSR shape triggered by notes or a fixed key.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Sync</strong> sets the time unit for Attack, Hold, Decay, and Release.</p><p><strong>SYNCED</strong> (default) follows MIDI Clock. Times show as note values (<strong>1/16</strong>, <strong>1/8</strong>, <strong>1/4</strong>, <strong>1/2</strong>, <strong>1/1</strong>, <strong>2 BARS</strong>, …). Any other time shows a number with <strong>T</strong>.</p><p><strong>FREE</strong> uses milliseconds and runs with no MIDI Clock.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Bypass</td><td>0 – 1</td><td>When on, Dest returns to rest and MIDI passes through unchanged.</td></tr><tr><td>Trigger</td><td>0</td><td>What starts the envelope: mono, keyed, polyphonic, or looping.</td></tr><tr><td>Key Note</td><td>0 – 127</td><td>Note that starts the envelope when Trigger is Key.</td></tr><tr><td>Sync</td><td>0 – 1</td><td>SYNCED follows MIDI Clock. FREE uses milliseconds and does not need Clock.</td></tr><tr><td>Attack</td><td>0 – 768</td><td>Time to rise to full level after a trigger.</td></tr><tr><td>Hold</td><td>0 – 768</td><td>Time the peak is held before decay.</td></tr><tr><td>Decay</td><td>0 – 768</td><td>Time to fall from the peak to the sustain level.</td></tr><tr><td>Sustain</td><td>0 – 100</td><td>Level held while the note is down (0–100%).</td></tr><tr><td>Release</td><td>0 – 768</td><td>After you let go, how long the note stays on while the destination fades.</td></tr><tr><td>Curve</td><td>0 – 1</td><td>Shape of Attack, Decay, and Release: LINEAR or LOG.</td></tr><tr><td>Depth</td><td>-100 – 100</td><td>How far the envelope moves the destination (−100 to +100%).</td></tr><tr><td>Offset</td><td>0 – 100</td><td>Level before the envelope is added (0–100%).</td></tr><tr><td>Dest</td><td>0</td><td>MIDI message the envelope drives (CC, pitch bend, and so on).</td></tr><tr><td>Dest MSB</td><td>0 – 127</td><td>High byte of the destination (NRPN, RPN, or CC MSB).</td></tr><tr><td>Dest LSB</td><td>0 – 127</td><td>Low byte of the destination (NRPN, RPN, or CC number).</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>On</td><td>Device is bypassed. Dest returns to rest; other messages pass through.</td></tr></tbody></table><h3 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Mono</td><td>One envelope. A new note starts it again.</td></tr><tr><td style="text-align:right;">1</td><td>Key</td><td>Starts only from Key Note.</td></tr><tr><td style="text-align:right;">2</td><td>Poly</td><td>One envelope per held note.</td></tr><tr><td style="text-align:right;">3</td><td>Loop</td><td>Keeps cycling while notes are held.</td></tr></tbody></table><h3 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>FREE</td><td>Times are milliseconds. Runs without MIDI Clock.</td></tr><tr><td style="text-align:right;">1</td><td>SYNCED</td><td>Times follow MIDI Clock (default).</td></tr></tbody></table><p>Switching from <strong>FREE</strong> to <strong>SYNCED</strong> sets each time to the nearest note value.</p><h3 id="curve" tabindex="-1">Curve <a class="header-anchor" href="#curve" aria-label="Permalink to &quot;Curve&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>LINEAR</td><td>Attack, Decay, and Release are straight ramps.</td></tr><tr><td style="text-align:right;">1</td><td>LOG</td><td>Attack, Decay, and Release rise quickly, then ease into the target.</td></tr></tbody></table><h3 id="attack-hold-decay-release" tabindex="-1">Attack, Hold, Decay, Release <a class="header-anchor" href="#attack-hold-decay-release" aria-label="Permalink to &quot;Attack, Hold, Decay, Release&quot;">​</a></h3><p>On <strong>SYNCED</strong>, a time on this list shows the note name. Any other time shows the number and <strong>T</strong>.</p><p>On <strong>FREE</strong>, the number is milliseconds.</p><p>SYNCED names:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Time</th><th>Name</th></tr></thead><tbody><tr><td style="text-align:right;">2</td><td>1/64</td></tr><tr><td style="text-align:right;">3</td><td>1/32</td></tr><tr><td style="text-align:right;">6</td><td>1/16</td></tr><tr><td style="text-align:right;">12</td><td>1/8</td></tr><tr><td style="text-align:right;">24</td><td>1/4</td></tr><tr><td style="text-align:right;">48</td><td>1/2</td></tr><tr><td style="text-align:right;">96</td><td>1/1</td></tr><tr><td style="text-align:right;">192</td><td>2 BARS</td></tr><tr><td style="text-align:right;">384</td><td>4 BARS</td></tr><tr><td style="text-align:right;">768</td><td>8 BARS</td></tr></tbody></table><h3 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h3><p>After you let go, the note stays on while the destination fades. The note ends when Release finishes. Release <strong>0</strong> ends the note right away.</p><p><strong>Mono</strong> does this when the last note of a chord goes up. <strong>Poly</strong> fades each note on its own. <strong>Key</strong> does this only for Key Note. <strong>Loop</strong> ends the note as soon as you let go.</p><h3 id="dest" tabindex="-1">Dest <a class="header-anchor" href="#dest" aria-label="Permalink to &quot;Dest&quot;">​</a></h3><p>On the device the list is <strong>CC</strong>, <strong>Pitch Bend</strong>, <strong>Ch. Pressure</strong>, <strong>Poly AT</strong> (only when Trigger is Poly), <strong>CC 14-bit</strong>, <strong>NRPN</strong>, <strong>RPN</strong>, then <strong>Prog. Change</strong>.</p><p>With <strong>Poly</strong> and <strong>Poly AT</strong>, each held note sends its own pressure. Any other destination sends one message that follows the held note with the highest level.</p><table tabindex="0"><thead><tr><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td>CC</td><td>One control change.</td></tr><tr><td>Pitch Bend</td><td>Pitch wheel.</td></tr><tr><td>Ch. Pressure</td><td>Channel aftertouch.</td></tr><tr><td>Poly AT</td><td>Pressure per note. Shown only when Trigger is Poly.</td></tr><tr><td>CC 14-bit</td><td>14-bit control change (MSB and LSB).</td></tr><tr><td>NRPN</td><td>Non-registered parameter.</td></tr><tr><td>RPN</td><td>Registered parameter.</td></tr><tr><td>Prog. Change</td><td>Program change.</td></tr></tbody></table>',29))])}const v=r(i,[["render",h]]);export{b as __pageData,v as default};
